-- Accounts, sign-in identities, refresh tokens and profiles.
-- Times are integer milliseconds (UTC). Ids are 26-character ULIDs generated by the API.

CREATE TABLE users (
  id           TEXT PRIMARY KEY,
  created_at   INTEGER NOT NULL,
  updated_at   INTEGER NOT NULL,
  deleted_at   INTEGER,
  email        TEXT,
  display_name TEXT
);

-- Sign-in methods linked to a user. An anonymous (device) account has none.
CREATE TABLE identities (
  id         TEXT PRIMARY KEY,
  user_id    TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  provider   TEXT NOT NULL CHECK (provider IN ('google')),
  subject    TEXT NOT NULL,
  email      TEXT,
  created_at INTEGER NOT NULL,
  UNIQUE (provider, subject)
);
CREATE INDEX identities_user ON identities (user_id);

-- Only the SHA-256 of a refresh token is stored. A family is one sign-in on one device; using an
-- already-used token revokes the whole family.
CREATE TABLE refresh_tokens (
  id           TEXT PRIMARY KEY,
  user_id      TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  family_id    TEXT NOT NULL,
  token_hash   TEXT NOT NULL UNIQUE,
  device_label TEXT,
  created_at   INTEGER NOT NULL,
  expires_at   INTEGER NOT NULL,
  used_at      INTEGER,
  revoked_at   INTEGER
);
CREATE INDEX refresh_tokens_user ON refresh_tokens (user_id);
CREATE INDEX refresh_tokens_family ON refresh_tokens (family_id);
CREATE INDEX refresh_tokens_expiry ON refresh_tokens (expires_at);

CREATE TABLE user_profiles (
  user_id               TEXT PRIMARY KEY REFERENCES users (id) ON DELETE CASCADE,
  updated_at            INTEGER NOT NULL,
  timezone              TEXT NOT NULL DEFAULT 'UTC',
  locale                TEXT NOT NULL DEFAULT 'en',
  units                 TEXT NOT NULL DEFAULT 'metric' CHECK (units IN ('metric', 'imperial')),
  sex                   TEXT CHECK (sex IN ('female', 'male')),
  birth_year            INTEGER,
  height_cm             REAL,
  weight_kg             REAL,
  activity_level        TEXT CHECK (activity_level IN ('sedentary', 'light', 'moderate', 'active', 'very_active')),
  goal                  TEXT NOT NULL DEFAULT 'maintain' CHECK (goal IN ('lose', 'maintain', 'gain')),
  goal_rate_kg_per_week REAL NOT NULL DEFAULT 0,
  target_weight_kg      REAL,
  calorie_goal          INTEGER NOT NULL DEFAULT 2000,
  protein_goal_g        INTEGER NOT NULL DEFAULT 125,
  carb_goal_g           INTEGER NOT NULL DEFAULT 225,
  fat_goal_g            INTEGER NOT NULL DEFAULT 67,
  goals_are_custom      INTEGER NOT NULL DEFAULT 0,
  onboarded_at          INTEGER
);
